static const SceneItem kScenes[] = {
  { "Sunburst Spiral", 30, 40, kFrames_spiral },
  { "Vortex Flow", 30, 40, kFrames_anim2 },
};

static const uint8_t kScenesCount = sizeof(kScenes) / sizeof(kScenes[0]);

uint8_t count() {
  return kScenesCount;
}

const SceneItem* getScene(uint8_t idx) {
  if (idx >= kScenesCount) idx = 0;
  return &kScenes[idx];
}

const uint8_t* getFrame(uint8_t sceneIdx, uint8_t frameIdx) {
  if (sceneIdx >= kScenesCount) sceneIdx = 0;
  const SceneItem& sc = kScenes[sceneIdx];
  if (frameIdx >= sc.frameCount) frameIdx = 0;
  return (const uint8_t*)pgm_read_ptr(&(sc.frames[frameIdx]));
}

